-- ERP NOX · 014_importar_acabados_semiacabados.sql
-- Cadastro de PRODUTOS DE VENDA (acabado), SEMIACABADOS, KITS e FERRAMENTAS,
-- cruzando o cadastro do Tiny com a TABELA DE CUSTOS E PREÇOS (09/10/2026):
--   · semiacabado: 294 ativos, 112 inativos
--   · ferramenta: 35 ativos, 8 inativos
--   · acabado: 508 ativos, 127 inativos
--   · kit: 5 ativos, 0 inativos
--   · materia_prima: 1 ativos, 0 inativos
-- Regras:
--   · Ativo = teve movimento no Tiny desde 2025, OU está na tabela de custos, OU é usado em ficha técnica
--   · EAN (GTIN) e NCM vêm da tabela de custos; o grupo vem da aba (Intake, Ponteira, Defletor...)
--   · Itens da tabela de custos que não estão no cadastro do Tiny entram com observação "conferir descrição"
--   · Correções: 4000236 ADESIVO BRINDE vira matéria-prima (está em 199 fichas);
--     2000188 FLANGE V-BAND vira semiacabado (corte a laser)
--   · Todos entram como "não revisado". Preço não é importado (fica para a Precificação).
-- Como usar: Supabase → SQL Editor → New → colar tudo → Run (depois do 010 ao 013).
-- Pode rodar de novo sem duplicar.
-- =====================================================================
alter table public.produtos disable trigger auditoria;

